      const p = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.18, 1.8, 6), std(0x3f3529, 0.9));
      p.position.set(10 + i * 7, 0.9, 98); g.add(p);
    }
    const reeds = std(0x4b5138, 0.95);
    for (let i = 0; i < 70; i++) {
