  makeStreetLamp(x, z) {
    const g = new THREE.Group(); this.scene.add(g);
    const iron = std(0x1b201e, 0.7, 0.4);
    this.makeCylinder(g, x, 2.4, z, 0.06, 0.1, 4.8, iron, 6);
