.btn-primary:hover:after{transform:translateX(120%)}
.btn-ghost{border:1px solid rgba(232,226,212,.28);padding:11px 22px;font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--bone-2);border-radius:2px;transition:.2s;background:rgba(255,255,255,.025)}
