.btn-link{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid transparent;padding-bottom:2px;transition:.2s}
.btn-link:hover{color:var(--bone);border-color:var(--muted)}

/* ============ HUD ============ */
#hud{position:absolute;inset:0;z-index:10;pointer-events:none;font-family:var(--sans)}
