.stress-word.warn{color:#c9a06a}.stress-word.bad{color:var(--rust-2)}.stress-word.critical{color:#e4533a;animation:stressPulse 2.4s infinite}
@keyframes stressPulse{0%,100%{opacity:1}50%{opacity:.5}}

.objective{position:absolute;top:24px;right:26px;margin-top:47px;width:302px;padding:15px 18px 14px;background:linear-gradient(135deg,rgba(15,19,20,.82),rgba(10,13,14,.62));border:1px solid rgba(232,226,212,.13);border-left:2px solid var(--rust);backdrop-filter:blur(10px);box-shadow:0 16px 40px rgba(0,0,0,.35)}
