.pulse{width:5px;height:5px;border-radius:50%;background:var(--rust-2);box-shadow:0 0 0 0 rgba(194,90,64,.6);animation:pulse 2.2s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(194,90,64,.55)}70%{box-shadow:0 0 0 8px rgba(194,90,64,0)}100%{box-shadow:0 0 0 0 rgba(194,90,64,0)}}
.objective h3{font-family:var(--serif);font-size:19px;font-weight:600;letter-spacing:.01em;margin:7px 0 4px;color:var(--bone)}
