.meter{position:relative;flex:1;height:4px;background:rgba(255,255,255,.1);overflow:hidden}
.meter i{display:block;height:100%;background:var(--bone-2);transition:width .4s ease,background .6s}
.meter.stress i{background:linear-gradient(90deg,#7f8a72,#b09258)}
.meter.stress.bad i{background:linear-gradient(90deg,#9a4e38,#c25a40)}
