.hud-tools{display:flex;flex-wrap:wrap;gap:10px 14px;margin-top:4px;align-items:center;opacity:.8}
.tool{font-family:var(--mono);font-size:7.5px;letter-spacing:.1em;color:var(--muted);display:flex;align-items:center;gap:5px;text-transform:uppercase}
.tool .keycap{height:17px;min-width:17px;font-size:8px}
