.toast-stack{position:absolute;right:26px;bottom:110px;display:flex;flex-direction:column;align-items:flex-end;gap:7px;z-index:12}
.toast{display:flex;align-items:flex-start;gap:10px;max-width:330px;padding:10px 14px;background:rgba(12,15,16,.92);border:1px solid rgba(232,226,212,.15);border-left:2px solid var(--gold);box-shadow:0 14px 40px rgba(0,0,0,.5);animation:toastIn .35s ease both;backdrop-filter:blur(10px)}
