432:   box(world, loc, -3.2, -1.55, -4.0, 5.2, 0.2, 2.8, materials.darkWood);
433:   // Nine sockets and a worn ring are the undercroft's central evidence tableau.
434:   const ring = new THREE.Mesh(new THREE.TorusGeometry(2.15, 0.045, 6, 36), materials.brass);
435:   ring.rotation.x = Math.PI / 2;
436:   ring.position.copy(point(loc, 0, -3.53, 0));
437:   (loc.group || world.scene).add(ring);
438:   for (let i = 0; i < 9; i++) {
439:     const a = i * Math.PI * 2 / 9;
440:     cylinder(world, loc, Math.cos(a) * 2.15, -3.43, Math.sin(a) * 2.15, 0.07, 0.08, 0.3, materials.candle, 8);
441:   }
442:   const mark = box(world, loc, 0, -3.51, 0, 0.34, 0.035, 0.34, materials.evidence);
443:   const medal = cylinder(world, loc, -3.25, -1.42, -4.0, 0.23, 0.23, 0.07, materials.silver, 16);
444:   addEvidence(world, 'chapelBasement', loc, 0, mark);
445:   addEvidence(world, 'chapelBasement', loc, 1, medal);
446:   const light = new THREE.PointLight(0xb89563, 0.45, 16, 2);
447:   light.position.copy(point(loc, 0, -1.0, 0));
448:   (loc.group || world.scene).add(light);
449:   return light;
