121: function addEvidence(world, placeId, loc, index, itemMesh) {
122:   const record = evidenceByPlace[placeId]?.[index];
123:   if (!record) return;
124:   const [suffix, label, description] = record;
125:   const position = new THREE.Vector3();
126:   itemMesh.getWorldPosition(position);
127:   addInteractable(world, {
128:     id: `${placeId}:${suffix}`,
129:     position,
130:     label,
131:     description,
132:     kind: 'evidence',
133:     location: placeId,
134:     object: itemMesh,
135:   });
136: }
