173: function addBuildingPortals(world, id, loc) {
174:   const { x, z, w, d } = loc;
175:   const door = loc.door || 'south';
176:   let exterior, interior;
177:   if (door === 'north') {
178:     exterior = [x, 1, z - d / 2 - 1.4];
179:     interior = [x, 1, z - d / 2 + 1.7];
180:   } else if (door === 'east') {
181:     exterior = [x + w / 2 + 1.4, 1, z];
182:     interior = [x + w / 2 - 1.7, 1, z];
183:   } else if (door === 'west') {
184:     exterior = [x - w / 2 - 1.4, 1, z];
185:     interior = [x - w / 2 + 1.7, 1, z];
186:   } else {
187:     exterior = [x, 1, z + d / 2 + 1.4];
188:     interior = [x, 1, z + d / 2 - 1.7];
189:   }
190:   addPortalPair(world, id, loc, exterior, interior);
191: }
