205: function evidenceProp(world, placeId, loc, index, x, y, z, type = 'paper') {
206:   let mesh;
207:   if (type === 'medal') {
208:     mesh = cylinder(world, loc, x, y, z, 0.2, 0.2, 0.055, materials.brass, 16);
209:     mesh.rotation.x = Math.PI / 2;
210:     cylinder(world, loc, x, y + 0.15, z, 0.035, 0.035, 0.25, materials.brass, 8);
211:   } else if (type === 'candle') {
212:     mesh = cylinder(world, loc, x, y, z, 0.09, 0.1, 0.48, materials.candle, 8);
213:     cylinder(world, loc, x, y + 0.27, z, 0.025, 0.025, 0.09, materials.evidence, 6);
214:   } else if (type === 'cup') {
215:     mesh = cylinder(world, loc, x, y, z, 0.18, 0.14, 0.28, materials.ceramic, 12);
216:   } else if (type === 'fiber') {
217:     mesh = box(world, loc, x, y, z, 0.42, 0.025, 0.035, materials.cloth, 0.4);
218:   } else {
219:     mesh = box(world, loc, x, y, z, 0.48, 0.055, 0.64, type === 'photo' ? materials.paper : materials.evidence, (index % 2 ? -0.12 : 0.08));
220:     if (type === 'book') box(world, loc, x, y + 0.045, z, 0.42, 0.025, 0.58, materials.paper, 0.03);
221:   }
222:   addEvidence(world, placeId, loc, index, mesh);
223:   return mesh;
224: }
